// Resolves the bounce against a set of overlapped bricks. `prevX/prevY` is
// where the ball was before the move: the face it entered through decides
// which axes invert (a corner entry inverts both). If the ball was already
// inside the brick on both axes (e.g. it spawned inside), the axis of least
// penetration wins. The ball is then pushed out of EVERY overlapped brick
// along the flipped axes, in the direction it now travels.
// `flips` records which axes were already inverted during this pass, so two
// bricks of the same seam cannot cancel each other's bounce.
function bounce(ball, overlapped, prevX, prevY, flips) {
  const brick = overlapped[0];
  const fromTop = prevY + ball.r <= brick.y;
  const fromBottom = prevY - ball.r >= brick.y + brick.h;
  const fromLeft = prevX + ball.r <= brick.x;
  const fromRight = prevX - ball.r >= brick.x + brick.w;
  const vertical = fromTop || fromBottom;
  const horizontal = fromLeft || fromRight;

  let flipX = false;
  let flipY = false;
  if (vertical && horizontal) {
    // Corner: both axes invert.
    flipX = true;
    flipY = true;
  } else if (vertical) {
    flipY = true;
  } else if (horizontal) {
    flipX = true;
  } else {
    // Already inside on both axes: least-penetration axis, corner on a tie.
    const px = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
    const py = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
    if (px < py) flipX = true;
    else if (py < px) flipY = true;
    else {
      flipX = true;
      flipY = true;
    }
  }

  if (flipX) {
    if (!flips.vx) {
      ball.vx = -ball.vx;
      flips.vx = true;
    }
    // The ball leaves through the side it now travels toward.
    pushAxis(ball, overlapped, 'x', Math.sign(ball.vx));
  }
  if (flipY) {
    if (!flips.vy) {
      ball.vy = -ball.vy;
      flips.vy = true;
    }
    pushAxis(ball, overlapped, 'y', Math.sign(ball.vy));
  }
}

// Pushes the ball outside every brick of the list, along one axis, in the
// given direction (-1 = toward x/y = 0, +1 = away).
function pushAxis(ball, bricks, axis, dir) {
  for (const brick of bricks) {
    if (axis === 'x') {
      if (dir < 0) ball.x = Math.min(ball.x, brick.x - ball.r);
      else ball.x = Math.max(ball.x, brick.x + brick.w + ball.r);
    } else {
      if (dir < 0) ball.y = Math.min(ball.y, brick.y - ball.r);
      else ball.y = Math.max(ball.y, brick.y + brick.h + ball.r);
    }
  }
}

