  function pushAxis(ball, brick, axis) {
    if (axis === 'x') {
      const left = ball.x + ball.r - brick.x;
      const right = brick.x + brick.w - (ball.x - ball.r);
      if (left < right) ball.x = brick.x - ball.r;
      else ball.x = brick.x + brick.w + ball.r;
    } else {
      const top = ball.y + ball.r - brick.y;
      const bottom = brick.y + brick.h - (ball.y - ball.r);
      if (top < bottom) ball.y = brick.y - ball.r;
      else ball.y = brick.y + brick.h + ball.r;
    }
  }
  function bounce(ball, overlapped, prevX, prevY, flips) {
    const brick = overlapped[0];
    const fromTop = prevY + ball.r <= brick.y;
    const fromBottom = prevY - ball.r >= brick.y + brick.h;
    const fromLeft = prevX + ball.r <= brick.x;
    const fromRight = prevX - ball.r >= brick.x + brick.w;
    const vertical = fromTop || fromBottom;
    const horizontal = fromLeft || fromRight;
    let flipX = false, flipY = false;
    if (vertical && horizontal) { flipX = true; flipY = true; }
    else if (vertical) flipY = true;
    else if (horizontal) flipX = true;
    else {
      const px = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
      const py = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
      if (px < py) flipX = true;
      else if (py < px) flipY = true;
      else { flipX = true; flipY = true; }
    }
    if (flipX) { if (!flips.vx) { ball.vx = -ball.vx; flips.vx = true; } pushAxis(ball, brick, 'x'); }
    if (flipY) { if (!flips.vy) { ball.vy = -ball.vy; flips.vy = true; } pushAxis(ball, brick, 'y'); }
  }
  const s = createState(1);
  s.ball.x = 233; s.ball.y = 37; s.ball.vx = ballSpeed(1); s.ball.vy = ballSpeed(1);
  const dx = s.ball.vx*0.05, dy = s.ball.vy*0.05;
