    return {
      lost,
      brickDead: brickAt(state, 0, 3).alive === false,
      vyUp: ball.vy < 0,
      aboveBrick: ball.y + ball.r <= brickAt(state, 0, 3).y,
    };
  };

  assert.deepEqual(run(30, 3), run(144, 10));
});

