// Defect #8 (dt dependence): the same scenario must play out identically at
// 30 fps and at 144 fps. At level 22 a single 30 fps step (71.7 px) fully
// crosses the 34 px-thick brick: only the fixed-distance sub-stepping makes
// the two frame rates agree.
test('physics: same outcome at 30 fps and 144 fps', () => {
  const run = (fps, frames) => {
    const state = createState(22);
    for (const b of state.bricks) b.alive = false;
    const brick = brickAt(state, 4, 3);
    brick.alive = true;
    const ball = state.ball;
    ball.x = 280; // centered on the survivor
    ball.y = 119; // 34 px above its top
    ball.vx = 0;
    ball.vy = ballSpeed(22);
    let lost = false;
    for (let i = 0; i < frames; i++) {
      if (step(state, 1 / fps)) lost = true;
    }
    return {
      lost,
      brickDead: brick.alive === false,
      vyUp: ball.vy < 0,
      aboveBrick: ball.y + ball.r <= brick.y,
    };
  };

  assert.deepEqual(run(30, 2), run(144, 10));
});

