        else { s.ball = createState(s.level).ball; }
      }
      if (s.bricks.every((br) => !br.alive)) {
        s.level += 1;
        if (s.level > 12) { console.log('GAME OK: reached level', s.level, 'game', g); break; }
        s.ball = createState(s.level).ball;
        s.bricks = createState(s.level).bricks;
      }
      if (b.y > 490 && !lost) { console.log('STUCK below field, game', g, 'frame', frames); process.exit(1); }
    }
  }
  console.log('simulation done');
});
