// through the paddle band (PADDLE_H + 2*BALL_R = 26 px) in a single test,
// whatever the level and the dt. Making the test distance fixed (not tied to
// dt) is what makes the physics frame-rate independent.
const COLLISION_SUBSTEP = 8;

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the bricks, the walls and the paddle. Brick collision moved out of the
// render loop `frame()` so the physics is testable pure logic.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle, bricks } = state;

  // Sub-divide the movement: every sub-step stays shorter than the thinnest
  // obstacle, so a collision can never be skipped, however fast the ball.
  const dx = ball.vx * dt;
  const dy = ball.vy * dt;
  const distance = Math.hypot(dx, dy);
  const sub = Math.max(1, Math.ceil(distance / COLLISION_SUBSTEP));
  const dts = dt / sub;

  for (let i = 0; i < sub; i++) {
    let prevX = ball.x;
    let prevY = ball.y;
    // Move with the CURRENT velocity: a bounce mid-step must redirect the
    // remaining sub-steps too (|v| is conserved by every bounce, so each
    // sub-step still stays shorter than COLLISION_SUBSTEP).
    ball.x += ball.vx * dts;
    ball.y += ball.vy * dts;

    // Bricks: every brick the ball overlaps is destroyed and scored, then the
    // bounce is resolved against the first of them (row-major order, so the
    // choice is deterministic). `flips` guarantees at most one inversion per
    // axis per sub-step: two bricks of the same seam touched together must not
    // cancel each other's bounce.
    const flips = { vx: false, vy: false };
    let guard = 0;
    while (guard++ < 4) {
      // Only live bricks act as obstacles. Two bricks of the same seam touched
      // in the same pass die together and the push-out below clears the ball
      // from BOTH footprints in one go.
      const overlapped = bricks.filter((b) => b.alive && collides(ball, b));
      if (overlapped.length === 0) break;
      for (const brick of overlapped) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
      bounce(ball, overlapped, prevX, prevY, flips);
      // The ball moved during the push-out: the next resolution must judge its
      // entry face from the pushed position, not from before the whole sub-step.
      prevX = ball.x;
      prevY = ball.y;
    }

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      // Rebound angle from where the paddle was hit, then renormalized so the
      // ball leaves at exactly the level's speed whatever the hit point.
      const speed = ballSpeed(state.level);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      const dirX = 0.6 * hit;
      const dirY = -1;
      const norm = Math.hypot(dirX, dirY);
      ball.vx = (speed * dirX) / norm;
      ball.vy = (speed * dirY) / norm;
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

