// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// Row-major brick lookup: makeBricks pushes row 0 first, then row 1, ...
function brickAt(state, row, col) {
  return state.bricks[row * BRICK_COLS + col];
}

// --- Brick bounce: the ball must bounce off bricks, not plow through ------

// Defect #1 (root): frame() killed the brick but never deflected the ball, so
// a head-on hit let it pass straight through. It must bounce back up.
test('bricks: head-on top face hit bounces the ball back up', () => {
  const state = createState(1);
  const brick = brickAt(state, 0, 3); // x: 244..316, y: 48..68
  const ball = state.ball;
  ball.x = 280; // centered on the brick
  ball.y = 29; // ball bottom 12 px above the brick top
  ball.vx = 0;
  ball.vy = ballSpeed(1); // heading down

  const lost = step(state, 0.05);

  assert.equal(lost, false);
  assert.equal(brick.alive, false, 'the touched brick must be destroyed');
  assert.ok(ball.vy < 0, 'vy must point up after a top-face bounce');
  assert.ok(ball.y + ball.r <= brick.y, 'the ball must end above the brick');
});

// Defect #1 (root), bottom face: symmetric case, ball coming up from below.
test('bricks: head-on bottom face hit bounces the ball back down', () => {
  const state = createState(1);
  const brick = brickAt(state, 4, 3); // x: 244..316, y: 160..180
  const ball = state.ball;
  ball.x = 280;
  ball.y = 193; // ball top 6 px below the brick bottom
  ball.vx = 0;
  ball.vy = -ballSpeed(1); // heading up

  step(state, 0.03);

  assert.equal(brick.alive, false);
  assert.ok(ball.vy > 0, 'vy must point down after a bottom-face bounce');
  assert.ok(ball.y - ball.r >= brick.y + brick.h, 'the ball must end below the brick');
});

// Defect #1 (root), side face: vx must flip and the ball be pushed aside.
// The grid is dense (BRICK_GAP < ball diameter), so the neighbor is killed
// first to open a clear lane toward the side face.
test('bricks: side face hit flips vx and pushes the ball out', () => {
  const state = createState(1);
  brickAt(state, 0, 2).alive = false; // open the lane
  const brick = brickAt(state, 0, 3);
  const ball = state.ball;
  ball.x = 230; // right edge 7 px left of the brick
  ball.y = 58; // vertically centered on the brick
  ball.vx = ballSpeed(1); // heading right
  ball.vy = 0;

  step(state, 0.05);

  assert.equal(brick.alive, false);
  assert.ok(ball.vx < 0, 'vx must flip left after a left-face hit');
  assert.ok(ball.x + ball.r <= brick.x, 'the ball must end left of the brick');
});

// Defect #6 (paddle): a fast ball can skip the whole paddle band in one step
// (PADDLE_H + 2*BALL_R = 26 px < ballSpeed(6) * 0.05 = 35.5 px). The paddle
// must be caught by the same sub-stepped sweep, and the ball must always
// exit through the top.
test('paddle: fast ball cannot tunnel through the paddle', () => {
  const state = createState(6);
  const ball = state.ball;
  ball.x = 320; // paddle center
  ball.y = 440; // ball bottom 1 px above the paddle top
  ball.vx = 0;
  ball.vy = ballSpeed(6); // 710 px/s

  const lost = step(state, 0.05); // 35.5 px in a single step

  assert.equal(lost, false);
  assert.ok(ball.vy < 0, 'the ball must bounce off the paddle, not pass through');
  assert.ok(ball.y + ball.r <= state.paddle.y, 'the ball must exit through the top of the paddle');
  assert.ok(Math.abs(Math.hypot(ball.vx, ball.vy) - ballSpeed(6)) < 1e-9, 'speed conserved at the bounce');
});

// Defect #7 (speed): the paddle bounce scaled vx to 0.6 * speed * hit while
// keeping vy = -speed, so |v| drifted up to 1.166 * speed. The norm after
// any bounce must be exactly the level's speed.
test('paddle: bounce conserves the level speed', () => {
  const state = createState(1);
  const ball = state.ball;
  ball.x = 344; // off-center hit (hit = 0.5)
  ball.y = 440;
  ball.vx = 0;
  ball.vy = ballSpeed(1);

  step(state, 0.05);

  assert.ok(ball.vy < 0, 'the ball bounces up off the paddle');
  assert.ok(ball.vx > 0, 'an off-center hit keeps its horizontal direction');
  const speed = Math.hypot(ball.vx, ball.vy);
  assert.ok(Math.abs(speed - ballSpeed(1)) < 1e-9, `speed ${speed} must equal ${ballSpeed(1)}`);
});

// Defect #8 (dt dependence): the same scenario must play out identically at
// 30 fps and at 144 fps. At level 22 a single 30 fps step (71.7 px) fully
// crosses the 34 px-thick brick: only the fixed-distance sub-stepping makes
// the two frame rates agree.
test('physics: same outcome at 30 fps and 144 fps', () => {
  const run = (fps, frames) => {
    const state = createState(22);
    for (const b of state.bricks) b.alive = false;
    const brick = brickAt(state, 4, 3);
    brick.alive = true;
    const ball = state.ball;
    ball.x = 280; // centered on the survivor
    ball.y = 119; // 34 px above its top
    ball.vx = 0;
    ball.vy = ballSpeed(22);
    let lost = false;
    for (let i = 0; i < frames; i++) {
      if (step(state, 1 / fps)) lost = true;
    }
    return {
      lost,
      brickDead: brick.alive === false,
      vyUp: ball.vy < 0,
      aboveBrick: ball.y + ball.r <= brick.y,
    };
  };

  assert.deepEqual(run(30, 2), run(144, 10));
});
// a single-axis flip would let the ball scrape along the side.
// Defect #4 (corner): entering through a corner inverts BOTH components —
// a single-axis flip would let the ball scrape along the side.
test('bricks: corner hit inverts both components', () => {
  const state = createState(1);
  brickAt(state, 0, 2).alive = false; // open the lane so the corner is clean
  const brick = brickAt(state, 0, 3);
  const ball = state.ball;
  ball.x = 233; // top-left corner of the brick: 244, 48
