// Defect #5 (tunneling): a single step at max speed travels further than a
// brick is thick (BRICK_H + 2*BALL_R = 34 px < ballSpeed(6) * 0.05 = 35.5 px).
// The step must be sub-divided so the crossing is never missed.
test('bricks: max-speed step (level 6) does not tunnel through a brick', () => {
  const state = createState(6);
  for (const b of state.bricks) b.alive = false;
  const brick = brickAt(state, 4, 3); // x: 244..316, y: 160..180 — the only survivor
  brick.alive = true;
  const ball = state.ball;
  ball.x = 280;
  ball.y = 152; // bottom 1 px above the brick, will cross it fully in one step
  ball.vx = 0;
  ball.vy = ballSpeed(6); // 710 px/s

  const lost = step(state, 0.05); // 35.5 px in a single step

  assert.equal(lost, false);
  assert.equal(brick.alive, false, 'the crossed brick must still be hit');
  assert.ok(ball.vy < 0, 'the ball must bounce off the brick, not pass through');
  assert.ok(ball.y + ball.r <= brick.y, 'the ball must end above the brick');
});
// Defect #3 (seam): the ball can straddle two bricks of the same row in one
// pass (BRICK_GAP = 8 < ball diameter = 14). Each brick inverts vx, the two
// flips cancel and the ball plows sideways through the seam: only ONE
// inversion per axis per pass is allowed.
test('bricks: seam between two bricks of the same row inverts vx only once', () => {
  const state = createState(1);
  const brickA = brickAt(state, 0, 2); // x: 164..236
  const brickB = brickAt(state, 0, 3); // x: 244..316
  const ball = state.ball;
  ball.x = 238; // straddles the 236..244 seam
  ball.y = 58; // vertically centered on the row
  ball.vx = ballSpeed(1); // heading right into the seam
  ball.vy = 0;

  step(state, 0.001);

  assert.equal(brickA.alive, false);
  assert.equal(brickB.alive, false);
  assert.ok(ball.vx < 0, 'vx must be inverted exactly once (no seam cancellation)');
  const liveOverlaps = state.bricks.filter((b) => b.alive && collides(ball, b));
  assert.deepEqual(liveOverlaps, [], 'the ball must not overlap any live brick');
});
test('bricks: ball is pushed back out of the brick (no sticky overlap)', () => {
  const state = createState(1);
  const brick = brickAt(state, 0, 3);
  const ball = state.ball;
  ball.x = 280;
  ball.y = 56; // spawned INSIDE the brick
  ball.vx = 100;
  ball.vy = 100;

  step(state, 0.001);

  assert.equal(brick.alive, false);
  assert.equal(collides(ball, brick), false, 'ball must be outside the brick after resolution');
  assert.ok(ball.vy < 0, 'the least-penetration axis is vertical here');
